//! `soiree dom`: the page's names as Rust types. A page's HTML and CSS are the
//! only place where an id, a class, a `data-*` attribute or a CSS property is
//! spelled; this writes a module where each of them is a constant, so the
//! Rust side can only name what the page declares. The rules forbid the raw
//! string methods of `web_sys` everywhere else.
//!
//! The generated file starts with its own recipe:
//!
//! ```text
//! // @generated by `soiree dom` …
//! // html: ../../../web/index.html
//! // css: ../../../web/style.css
//! // id: labelName textarea
//! // data: row
//! // attr: contenteditable
//! // class: is-connected
//! ```
//!
//! Paths are relative to the generated file. `id:` declares an element only
//! the Rust side creates (with its tag, which gives its type); `data:` and
//! `attr:` declare attributes only the Rust side sets. `soiree check`
//! regenerates every such file and fails when one is stale.

use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::io::Write as _;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode, Stdio};

use crate::report::Report;
use crate::util::{self, Result};

/// The first line of every generated file.
pub const MARKER: &str = "// @generated by `soiree dom`";

const HEADER: &str = "// @generated by `soiree dom`: do not edit. Change the page or the lines\n\
// below, then run `soiree dom <this file>`; `soiree check` fails when it is stale.";

/// What the page declares.
#[derive(Debug, Default, PartialEq, Eq)]
pub struct Names {
    /// Element ids, with the tag that gives their type.
    pub ids: BTreeMap<String, String>,
    pub classes: BTreeSet<String>,
    /// `data-*` attributes, without the prefix.
    pub data: BTreeSet<String>,
    /// Other attributes.
    pub attrs: BTreeSet<String>,
    /// CSS properties, custom ones (`--hue`) included.
    pub props: BTreeSet<String>,
    /// Value categories explicitly declared by the owning stylesheet.
    pub prop_types: BTreeMap<String, BTreeSet<String>>,
    /// Tags of the page's HTML elements.
    pub tags: BTreeSet<String>,
    /// Ids a CSS selector names, checked against `ids`.
    css_ids: BTreeSet<String>,
}

/// The recipe at the top of a generated file.
#[derive(Debug, Default, PartialEq, Eq)]
pub struct Recipe {
    pub html: Vec<String>,
    pub css: Vec<String>,
    /// `(id, tag)` of elements only the Rust side creates.
    pub ids: Vec<(String, String)>,
    pub data: Vec<String>,
    pub attrs: Vec<String>,
    /// Tags only the Rust side creates.
    pub tags: Vec<String>,
    /// Classes only the Rust side sets, without a style.
    pub classes: Vec<String>,
}

pub fn run(args: &[String]) -> ExitCode {
    match command(args) {
        Ok(message) => {
            println!("{message}");
            ExitCode::SUCCESS
        }
        Err(error) => {
            eprintln!("soiree dom : {error}");
            ExitCode::FAILURE
        }
    }
}

/// `soiree dom <file> [--html H]… [--css C]… [--id ID TAG]… [--data D]… [--attr A]…`:
/// starts from the file's own recipe when it exists; `--html` and `--css`
/// replace its pages, the other options add to it.
fn command(args: &[String]) -> Result<String> {
    let mut given = Recipe::default();
    let mut file = None;
    let mut rest = args.iter();
    while let Some(arg) = rest.next() {
        let mut value = || {
            rest.next()
                .cloned()
                .ok_or_else(|| format!("{arg} sans valeur"))
        };
        match arg.as_str() {
            "--html" => given.html.push(value()?),
            "--css" => given.css.push(value()?),
            "--data" => given.data.push(value()?),
            "--attr" => given.attrs.push(value()?),
            "--tag" => given.tags.push(value()?),
            "--class" => given.classes.push(value()?),
            "--id" => {
                let id = value()?;
                given.ids.push((id, value()?));
            }
            flag if flag.starts_with('-') => return Err(format!("option inconnue {flag}")),
            path if file.is_none() => file = Some(PathBuf::from(path)),
            extra => return Err(format!("argument en trop {extra}")),
        }
    }
    let file = file.ok_or("il manque le fichier à générer (par exemple crates/web/src/page.rs)")?;
    let mut recipe = if file.exists() {
        parse_recipe(&util::read(&file)?)?
    } else {
        Recipe::default()
    };
    if !given.html.is_empty() {
        recipe.html = given.html;
    }
    if !given.css.is_empty() {
        recipe.css = given.css;
    }
    // `--id` again with another tag retypes that element.
    for (id, tag) in given.ids {
        recipe.ids.retain(|(known, _)| *known != id);
        recipe.ids.push((id, tag));
    }
    for (list, added) in [
        (&mut recipe.data, given.data),
        (&mut recipe.attrs, given.attrs),
        (&mut recipe.tags, given.tags),
        (&mut recipe.classes, given.classes),
    ] {
        for name in added {
            if !list.contains(&name) {
                list.push(name);
            }
        }
    }
    let text = generate(&file, &recipe)?;
    util::write(&file, &text)?;
    Ok(format!(
        "{} écrit ; déclare-le avec `pub mod` à la racine du crate.",
        file.display()
    ))
}

/// Checks every generated file under `dir`.
pub fn check(dir: &Path, report: &mut Report) {
    let mut seen = 0_usize;
    let before = report.lines.len();
    for file in util::files_under(dir, &[".rs"], &["target", ".git", "node_modules", "pkg"]) {
        let Ok(text) = util::read(&file) else {
            continue;
        };
        if !text.starts_with(MARKER) {
            continue;
        }
        seen = seen.saturating_add(1);
        let shown = util::shown(&file, dir);
        match parse_recipe(&text).and_then(|recipe| generate(&file, &recipe)) {
            Ok(fresh) if fresh == text => {}
            Ok(_) => report.error(format!(
                "{shown} n'est plus à jour avec sa page : soiree dom {shown}"
            )),
            Err(error) => report.error(format!("{shown} : {error}")),
        }
    }
    if seen > 0 && report.lines.len() == before {
        report.ok(format!(
            "noms des pages à jour ({seen} module(s) soiree dom)"
        ));
    }
}

pub fn parse_recipe(text: &str) -> Result<Recipe> {
    let mut recipe = Recipe::default();
    for line in text.lines().skip(1) {
        let Some(line) = line.strip_prefix("// ") else {
            break;
        };
        let Some((key, value)) = line.split_once(':') else {
            continue;
        };
        let words = value.split_whitespace().map(str::to_owned);
        match key {
            "html" => recipe.html.extend(words),
            "css" => recipe.css.extend(words),
            "data" => recipe.data.extend(words),
            "attr" => recipe.attrs.extend(words),
            "tag" => recipe.tags.extend(words),
            "class" => recipe.classes.extend(words),
            "id" => {
                let words: Vec<String> = words.collect();
                let [id, tag] = words.as_slice() else {
                    return Err(format!(
                        "ligne `// id:{value}` : il faut `// id: <id> <balise>`"
                    ));
                };
                recipe.ids.push((id.clone(), tag.clone()));
            }
            _ => {}
        }
    }
    Ok(recipe)
}

/// The formatted module for `recipe`, its paths read relative to `file`.
pub fn generate(file: &Path, recipe: &Recipe) -> Result<String> {
    let base = file
        .parent()
        .filter(|parent| !parent.as_os_str().is_empty())
        .unwrap_or(Path::new("."));
    let mut names = Names::default();
    for html in &recipe.html {
        scan_html(&util::read(&base.join(html))?, &mut names)?;
    }
    for css in &recipe.css {
        scan_css(&util::read(&base.join(css))?, &mut names);
    }
    for (id, tag) in &recipe.ids {
        if names.ids.insert(id.clone(), tag.clone()).is_some() {
            return Err(format!(
                "#{id} est déjà dans la page : retire sa ligne `// id:`"
            ));
        }
    }
    names.data.extend(recipe.data.iter().cloned());
    names.attrs.extend(recipe.attrs.iter().cloned());
    names.tags.extend(recipe.tags.iter().cloned());
    names.classes.extend(recipe.classes.iter().cloned());
    if let Some(missing) = names.css_ids.iter().find(|id| !names.ids.contains_key(*id)) {
        return Err(format!(
            "le CSS cible #{missing}, qu'aucune page ne déclare (ajoute `// id: {missing} <balise>` s'il est créé en Rust)"
        ));
    }
    let source = module(recipe, &names)?;
    rustfmt(&source, base)
}

/// Formats with the `rustfmt` of the game's own toolchain: it runs in `dir`,
/// where `rust-toolchain.toml` applies.
fn rustfmt(source: &str, dir: &Path) -> Result<String> {
    let mut child = Command::new("rustfmt")
        .current_dir(dir)
        .args(["--edition", "2024", "--emit", "stdout"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(|error| format!("rustfmt : {error}"))?;
    child
        .stdin
        .take()
        .ok_or("rustfmt : pas d'entrée")?
        .write_all(source.as_bytes())
        .map_err(|error| format!("rustfmt : {error}"))?;
    let output = child
        .wait_with_output()
        .map_err(|error| format!("rustfmt : {error}"))?;
    if !output.status.success() {
        return Err(format!(
            "rustfmt refuse le module généré : {}",
            String::from_utf8_lossy(&output.stderr)
        ));
    }
    String::from_utf8(output.stdout).map_err(|error| format!("rustfmt : {error}"))
}

/// Reads ids, classes and attributes from HTML, and `<style>` bodies as CSS.
/// Comments and `<script>` bodies are skipped; elements inside `<svg>` are typed `Element`.
pub fn scan_html(html: &str, names: &mut Names) -> Result<()> {
    let mut rest = html;
    let mut svg_depth = 0_usize;
    while let Some(start) = rest.find('<') {
        rest = rest.get(start..).unwrap_or_default();
        if let Some(after) = rest.strip_prefix("<!--") {
            rest = after
                .find("-->")
                .map_or("", |end| after.get(end..).unwrap_or_default());
            continue;
        }
        let end = tag_end(rest);
        let inside = rest.get(1..end).unwrap_or_default().trim_end_matches('>');
        rest = rest.get(end..).unwrap_or_default();
        if let Some(closing) = inside.strip_prefix('/') {
            if closing.trim().eq_ignore_ascii_case("svg") {
                svg_depth = svg_depth.saturating_sub(1);
            }
            continue;
        }
        if inside.starts_with('!') || inside.starts_with('?') {
            continue;
        }
        let (tag, attributes) = split_tag(inside);
        let tag = tag.to_ascii_lowercase();
        let self_closing = inside.trim_end().ends_with('/');
        if tag == "svg" && !self_closing {
            svg_depth = svg_depth.saturating_add(1);
        }
        let typed = if svg_depth > 0 { "svg" } else { tag.as_str() };
        let structural = matches!(
            tag.as_str(),
            "html" | "head" | "body" | "meta" | "link" | "title" | "script" | "style" | "svg"
        );
        if svg_depth == 0 && !structural {
            names.tags.insert(tag.clone());
        }
        for (name, value) in attributes {
            match name.as_str() {
                "id" => {
                    if names.ids.insert(value.clone(), typed.to_owned()).is_some() {
                        return Err(format!("#{value} est déclaré deux fois dans la page"));
                    }
                }
                "class" => names
                    .classes
                    .extend(value.split_whitespace().map(str::to_owned)),
                "style" => {}
                data if data.starts_with("data-") => {
                    names
                        .data
                        .insert(data.trim_start_matches("data-").to_owned());
                }
                other => {
                    names.attrs.insert(other.to_owned());
                }
            }
        }
        if matches!(tag.as_str(), "script" | "style") && !self_closing {
            let closing = format!("</{tag}");
            let body_end = rest.find(&closing).unwrap_or(rest.len());
            if tag == "style" {
                scan_css(rest.get(..body_end).unwrap_or_default(), names);
            }
            rest = rest.get(body_end..).unwrap_or_default();
        }
    }
    Ok(())
}

/// The index just past the `>` that closes the tag at the start of `text`,
/// ignoring `>` inside quoted attribute values.
fn tag_end(text: &str) -> usize {
    let mut quote = None;
    for (at, c) in text.char_indices() {
        match (quote, c) {
            (None, '"' | '\'') => quote = Some(c),
            (Some(open), c) if c == open => quote = None,
            (None, '>') => return at.saturating_add(1),
            _ => {}
        }
    }
    text.len()
}

/// The tag name and the `(name, value)` attributes of a tag's inside.
fn split_tag(inside: &str) -> (String, Vec<(String, String)>) {
    let inside = inside.trim().trim_end_matches('/');
    let name_end = inside
        .find(|c: char| c.is_whitespace())
        .unwrap_or(inside.len());
    let (tag, mut rest) = inside.split_at(name_end);
    let mut attributes = Vec::new();
    loop {
        rest = rest.trim_start();
        if rest.is_empty() {
            break;
        }
        let name_end = rest
            .find(|c: char| c.is_whitespace() || c == '=')
            .unwrap_or(rest.len());
        let (name, after) = rest.split_at(name_end);
        rest = after.trim_start();
        let mut value = String::new();
        if let Some(after) = rest.strip_prefix('=') {
            let after = after.trim_start();
            let quote = after.chars().next().filter(|c| matches!(c, '"' | '\''));
            let (text, remaining) = if let Some(quote) = quote {
                let body = after.get(1..).unwrap_or_default();
                let end = body.find(quote).unwrap_or(body.len());
                (
                    body.get(..end).unwrap_or_default(),
                    body.get(end.saturating_add(1)..).unwrap_or_default(),
                )
            } else {
                let end = after.find(char::is_whitespace).unwrap_or(after.len());
                after.split_at(end)
            };
            text.clone_into(&mut value);
            rest = remaining;
        }
        // As written: SVG's names are case-sensitive (`viewBox`).
        if !name.is_empty() {
            attributes.push((name.to_owned(), value));
        }
    }
    (tag.to_owned(), attributes)
}

/// Reads class, id and attribute selectors, and declared properties, from CSS.
pub fn scan_css(css: &str, names: &mut Names) {
    for line in css.lines() {
        if let Some(declaration) = line
            .trim()
            .strip_prefix("/* soiree-type:")
            .and_then(|s| s.strip_suffix("*/"))
        {
            let words: Vec<_> = declaration.split_whitespace().collect();
            if let [name, kind] = words.as_slice() {
                names
                    .prop_types
                    .entry((*name).to_owned())
                    .or_default()
                    .insert((*kind).to_owned());
            } else {
                names
                    .prop_types
                    .entry(declaration.trim().to_owned())
                    .or_default();
            }
        }
    }
    let css = strip_comments(css);
    let mut prelude = String::new();
    // For each open block: whether it holds declarations.
    let mut blocks: Vec<bool> = Vec::new();
    for c in css.chars() {
        match c {
            '{' => {
                let text = prelude.trim();
                let nested = text.starts_with("@media")
                    || text.starts_with("@supports")
                    || text.starts_with("@container")
                    || text.starts_with("@layer");
                if !text.starts_with('@') {
                    scan_selector(text, names);
                }
                if blocks.last().copied().unwrap_or(false) {
                    // A nested rule inside declarations (`&:hover {`).
                    scan_selector(text.rsplit(';').next().unwrap_or_default(), names);
                }
                blocks.push(!nested);
                prelude.clear();
            }
            '}' => {
                if blocks.last().copied().unwrap_or(false) {
                    scan_declarations(&prelude, names);
                }
                let _: Option<bool> = blocks.pop();
                prelude.clear();
            }
            _ => prelude.push(c),
        }
    }
}

fn strip_comments(css: &str) -> String {
    let mut out = String::with_capacity(css.len());
    let mut rest = css;
    while let Some(start) = rest.find("/*") {
        out.push_str(rest.get(..start).unwrap_or_default());
        let after = rest.get(start.saturating_add(2)..).unwrap_or_default();
        rest = after.find("*/").map_or("", |end| {
            after.get(end.saturating_add(2)..).unwrap_or_default()
        });
    }
    out.push_str(rest);
    out
}

fn scan_selector(selector: &str, names: &mut Names) {
    let chars: Vec<char> = selector.chars().collect();
    let mut at = 0_usize;
    while let Some(&c) = chars.get(at) {
        at = at.saturating_add(1);
        match c {
            '.' | '#' => {
                let name = ident(&chars, &mut at);
                // `.5` in `:nth-child(2n+.5)` is not a class.
                if name.is_empty() || name.starts_with(|c: char| c.is_ascii_digit()) {
                    continue;
                }
                if c == '.' {
                    names.classes.insert(name);
                } else {
                    names.css_ids.insert(name);
                }
            }
            '[' => {
                let name = ident(&chars, &mut at).to_ascii_lowercase();
                if let Some(data) = name.strip_prefix("data-") {
                    names.data.insert(data.to_owned());
                } else if !name.is_empty() {
                    names.attrs.insert(name);
                }
            }
            '"' | '\'' => {
                while let Some(&next) = chars.get(at) {
                    at = at.saturating_add(1);
                    if next == c {
                        break;
                    }
                }
            }
            _ => {}
        }
    }
}

fn ident(chars: &[char], at: &mut usize) -> String {
    let mut name = String::new();
    while let Some(&c) = chars.get(*at) {
        if c.is_alphanumeric() || c == '-' || c == '_' {
            name.push(c);
            *at = at.saturating_add(1);
        } else {
            break;
        }
    }
    name
}

fn scan_declarations(block: &str, names: &mut Names) {
    // A custom property only read (`var(--hue)`) is one the Rust side sets.
    for (at, _) in block.match_indices("var(--") {
        let chars: Vec<char> = block
            .get(at.saturating_add(4)..)
            .unwrap_or_default()
            .chars()
            .collect();
        let mut end = 0_usize;
        let name = ident(&chars, &mut end);
        if name.len() > 2 {
            names.props.insert(name.to_ascii_lowercase());
        }
    }
    for declaration in block.split(';') {
        let Some((property, _)) = declaration.split_once(':') else {
            continue;
        };
        // What follows a nested rule's `}` is not cut by `;`.
        let property = property.rsplit('}').next().unwrap_or_default().trim();
        let valid = !property.is_empty()
            && property
                .chars()
                .all(|c| c.is_ascii_alphanumeric() || c == '-');
        if valid {
            names.props.insert(property.to_ascii_lowercase());
        }
    }
}

/// The `web_sys` type of an element of `tag`.
fn element_type(tag: &str) -> &'static str {
    let lower = tag.to_ascii_lowercase();
    if SVG_TAGS.contains(&lower.as_str()) || lower.starts_with("fe") {
        return "Element";
    }
    match tag {
        "a" => "HtmlAnchorElement",
        "button" => "HtmlButtonElement",
        "canvas" => "HtmlCanvasElement",
        "dialog" => "HtmlDialogElement",
        "div" => "HtmlDivElement",
        "form" => "HtmlFormElement",
        "h1" | "h2" | "h3" | "h4" | "h5" | "h6" => "HtmlHeadingElement",
        "img" => "HtmlImageElement",
        "input" => "HtmlInputElement",
        "label" => "HtmlLabelElement",
        "li" => "HtmlLiElement",
        "ol" => "HtmlOListElement",
        "option" => "HtmlOptionElement",
        "p" => "HtmlParagraphElement",
        "pre" => "HtmlPreElement",
        "select" => "HtmlSelectElement",
        "span" => "HtmlSpanElement",
        "template" => "HtmlTemplateElement",
        "textarea" => "HtmlTextAreaElement",
        "ul" => "HtmlUListElement",
        "video" => "HtmlVideoElement",
        _ => "HtmlElement",
    }
}

/// SVG's elements: `Element`, not an `Html…Element`.
const SVG_TAGS: &[&str] = &[
    "svg",
    "g",
    "defs",
    "symbol",
    "use",
    "path",
    "circle",
    "ellipse",
    "line",
    "polygon",
    "polyline",
    "rect",
    "text",
    "tspan",
    "image",
    "filter",
    "lineargradient",
    "radialgradient",
    "stop",
    "mask",
    "clippath",
    "pattern",
    "marker",
];

/// `tier-row`, `labelName` → `TIER_ROW`, `LABEL_NAME`.
pub fn const_name(name: &str) -> String {
    if let Some(custom) = name.strip_prefix("--") {
        return format!("VAR_{}", const_name(custom));
    }
    let mut out = String::new();
    let mut previous_lower = false;
    for c in name.chars() {
        if c == '-' || c == '_' || c == ':' {
            out.push('_');
            previous_lower = false;
        } else if c.is_ascii_uppercase() {
            if previous_lower {
                out.push('_');
            }
            out.push(c);
            previous_lower = false;
        } else {
            out.push(c.to_ascii_uppercase());
            previous_lower = c.is_ascii_lowercase() || c.is_ascii_digit();
        }
    }
    if out.starts_with(|c: char| c.is_ascii_digit()) || out.is_empty() {
        out.insert(0, 'N');
    }
    if matches!(out.as_str(), "SELF" | "SUPER" | "CRATE") {
        out.push('_');
    }
    out
}

/// One `pub mod` of constants, refusing two names that collide.
fn constants<'a>(
    out: &mut String,
    module: &str,
    doc: &str,
    entries: impl Iterator<Item = (&'a str, String, String)>,
) -> Result<()> {
    let mut seen: BTreeMap<String, &str> = BTreeMap::new();
    let _: std::fmt::Result = writeln!(out, "\n/// {doc}\npub mod {module} {{");
    for (name, ty, value) in entries {
        let constant = const_name(name);
        if let Some(other) = seen.insert(constant.clone(), name) {
            return Err(format!(
                "`{other}` et `{name}` donnent la même constante {module}::{constant} : renomme l'un d'eux"
            ));
        }
        let _: std::fmt::Result = writeln!(out, "    pub const {constant}: {ty} = {value};");
    }
    out.push_str("}\n");
    Ok(())
}

fn module(recipe: &Recipe, names: &Names) -> Result<String> {
    let mut out = String::new();
    out.push_str(HEADER);
    out.push('\n');
    for (key, values) in [("html", &recipe.html), ("css", &recipe.css)] {
        if !values.is_empty() {
            let _: std::fmt::Result = writeln!(out, "// {key}: {}", values.join(" "));
        }
    }
    for (id, tag) in &recipe.ids {
        let _: std::fmt::Result = writeln!(out, "// id: {id} {tag}");
    }
    for (key, values) in [
        ("data", &recipe.data),
        ("attr", &recipe.attrs),
        ("tag", &recipe.tags),
        ("class", &recipe.classes),
    ] {
        if !values.is_empty() {
            let _: std::fmt::Result = writeln!(out, "// {key}: {}", values.join(" "));
        }
    }
    out.push_str(RUNTIME);
    constants(
        &mut out,
        "id",
        "The page's elements, by id.",
        names.ids.iter().map(|(id, tag)| {
            let ty = element_type(tag);
            (
                id.as_str(),
                format!("super::Id<web_sys::{ty}>"),
                format!("super::Id::new({id:?})"),
            )
        }),
    )?;
    constants(
        &mut out,
        "class",
        "The classes the page and its stylesheets declare.",
        names.classes.iter().map(|c| {
            (
                c.as_str(),
                "super::Class".to_owned(),
                format!("super::Class({c:?})"),
            )
        }),
    )?;
    constants(
        &mut out,
        "data",
        "The `data-*` attributes.",
        names.data.iter().map(|d| {
            (
                d.as_str(),
                "super::Data".to_owned(),
                format!("super::Data({:?})", format!("data-{d}")),
            )
        }),
    )?;
    constants(
        &mut out,
        "attr",
        "The other attributes the page uses.",
        names.attrs.iter().map(|a| {
            (
                a.as_str(),
                "super::Attr".to_owned(),
                format!("super::Attr({a:?})"),
            )
        }),
    )?;
    properties(&mut out, names)?;
    constants(
        &mut out,
        "tag",
        "The elements the Rust side may create.",
        names.tags.iter().map(|tag| {
            let ty = element_type(tag);
            (
                tag.as_str(),
                format!("super::Tag<web_sys::{ty}>"),
                format!("super::Tag::new({tag:?})"),
            )
        }),
    )?;
    Ok(out)
}

fn properties(out: &mut String, names: &Names) -> Result<()> {
    for name in names.prop_types.keys() {
        if !names.props.contains(name) {
            return Err(format!("soiree-type : propriété CSS {name} absente"));
        }
    }
    let properties = names
        .props
        .iter()
        .map(|p| {
            let kind = property_type(p, names.prop_types.get(p))?;
            Ok((
                p.as_str(),
                format!("super::Prop<{kind}>"),
                format!("super::Prop::new({p:?})"),
            ))
        })
        .collect::<Result<Vec<_>>>()?;
    constants(
        out,
        "prop",
        "The CSS properties the stylesheets declare, custom ones included.",
        properties.into_iter(),
    )
}

fn property_type(name: &str, declared: Option<&BTreeSet<String>>) -> Result<String> {
    let standard = match name {
        "color" | "background-color" => Some("color"),
        "left" | "right" | "top" | "bottom" | "width" | "height" => Some("length"),
        "opacity" | "flex-grow" | "flex-shrink" => Some("number"),
        "animation-delay" | "animation-duration" | "transition-delay" | "transition-duration" => {
            Some("time")
        }
        "background-image" => Some("image"),
        _ => None,
    };
    let explicit = if let Some(kinds) = declared {
        if kinds.len() != 1 {
            return Err(format!("soiree-type : types contradictoires pour {name}"));
        }
        kinds.first().map(String::as_str)
    } else {
        None
    };
    if let (Some(standard), Some(explicit)) = (standard, explicit)
        && standard != explicit
    {
        return Err(format!(
            "soiree-type : {name} attend {standard}, pas {explicit}"
        ));
    }
    let kind = match explicit.or(standard) {
        Some("color") => "Color",
        Some("length") => "Length",
        Some("number") => "Number",
        Some("time") => "Time",
        Some("image") => "Image",
        Some(other) => {
            return Err(format!(
                "soiree-type : catégorie inconnue {other} pour {name}"
            ));
        }
        None => return Ok("()".into()),
    };
    Ok(format!("salon_web::style::{kind}"))
}

/// The typed accessors every generated module carries.
const RUNTIME: &str = r##"
#![expect(
    clippy::disallowed_methods,
    reason = "the one place where the page's names meet web_sys's string methods"
)]

use core::fmt::Display;
use core::marker::PhantomData;
use core::str::FromStr;

use wasm_bindgen::{JsCast, JsValue};
use web_sys::{Document, Element};

pub fn document() -> Result<Document, JsValue> {
    web_sys::window()
        .and_then(|window| window.document())
        .ok_or_else(|| JsValue::from_str("no document"))
}

/// An element of the page, with its type.
pub struct Id<T> {
    name: &'static str,
    kind: PhantomData<fn() -> T>,
}

impl<T> Clone for Id<T> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<T> Copy for Id<T> {}

impl<T> Id<T> {
    const fn new(name: &'static str) -> Self {
        Self {
            name,
            kind: PhantomData,
        }
    }

    /// Whether `element` is this one.
    pub fn is(self, element: &Element) -> bool {
        element.id() == self.name
    }

    /// Points `attr` of `element` at this one (`for`, `aria-labelledby`,
    /// `aria-controls`).
    pub fn refer(self, element: &Element, attr: Attr) -> Result<(), JsValue> {
        element.set_attribute(attr.0, self.name)
    }

    /// `url(#name)`, how CSS and SVG name it (`filter`, `fill`).
    pub fn url(self) -> String {
        format!("url(#{})", self.name)
    }
}

impl<T: JsCast> Id<T> {
    pub fn get(self) -> Result<T, JsValue> {
        document()?
            .get_element_by_id(self.name)
            .ok_or_else(|| JsValue::from_str(&format!("missing #{}", self.name)))?
            .dyn_into::<T>()
            .map_err(|_| JsValue::from_str(&format!("#{} has another type", self.name)))
    }
}

impl<T: AsRef<Element>> Id<T> {
    /// Gives a new element this id.
    pub fn give(self, element: &T) {
        element.as_ref().set_id(self.name);
    }
}

/// A class of the page's stylesheets.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Class(&'static str);

impl Display for Class {
    /// Its name, for a report.
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(self.0)
    }
}

impl Class {
    pub fn add_to(self, element: &Element) -> Result<(), JsValue> {
        element.class_list().add_1(self.0)
    }

    pub fn remove_from(self, element: &Element) -> Result<(), JsValue> {
        element.class_list().remove_1(self.0)
    }

    pub fn is_on(self, element: &Element) -> bool {
        element.class_list().contains(self.0)
    }

    /// Adds or removes the class.
    #[expect(
        clippy::fn_params_excessive_bools,
        reason = "the bool is the class's state itself"
    )]
    pub fn set(self, element: &Element, on: bool) -> Result<(), JsValue> {
        element
            .class_list()
            .toggle_with_force(self.0, on)
            .map(|_| ())
    }

    /// The closest ancestor (or self) with this class.
    pub fn closest(self, element: &Element) -> Option<Element> {
        element.closest(&format!(".{}", self.0)).ok().flatten()
    }
}

/// A `data-*` attribute. Its value goes through `Display` and `FromStr`, so
/// one Rust type writes it and reads it back.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Data(&'static str);

impl Data {
    pub fn set(self, element: &Element, value: &impl Display) -> Result<(), JsValue> {
        element.set_attribute(self.0, &value.to_string())
    }

    pub fn get<V: FromStr>(self, element: &Element) -> Option<V> {
        element.get_attribute(self.0)?.parse().ok()
    }

    pub fn has(self, element: &Element) -> bool {
        element.has_attribute(self.0)
    }

    pub fn remove(self, element: &Element) -> Result<(), JsValue> {
        element.remove_attribute(self.0)
    }

    /// The closest ancestor (or self) that carries this attribute.
    pub fn closest(self, element: &Element) -> Option<Element> {
        element.closest(&format!("[{}]", self.0)).ok().flatten()
    }
}

/// Another attribute the page uses.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Attr(&'static str);

impl Attr {
    pub fn set(self, element: &Element, value: &str) -> Result<(), JsValue> {
        element.set_attribute(self.0, value)
    }

    pub fn get(self, element: &Element) -> Option<String> {
        element.get_attribute(self.0)
    }

    pub fn has(self, element: &Element) -> bool {
        element.has_attribute(self.0)
    }

    pub fn remove(self, element: &Element) -> Result<(), JsValue> {
        element.remove_attribute(self.0)
    }

    /// Adds or removes a boolean attribute (`hidden`, `disabled`).
    #[expect(
        clippy::fn_params_excessive_bools,
        reason = "the bool is the attribute's presence itself"
    )]
    pub fn set_present(self, element: &Element, on: bool) -> Result<(), JsValue> {
        element.toggle_attribute_with_force(self.0, on).map(|_| ())
    }
}

/// A stylesheet property with its declared value category. Undeclared
/// categories have no setter; annotate them in CSS with `soiree-type`.
pub type Prop<V = ()> = salon_web::style::Property<V>;

/// An element the Rust side may create, with its type.
pub struct Tag<T> {
    name: &'static str,
    kind: PhantomData<fn() -> T>,
}

impl<T> Clone for Tag<T> {
    fn clone(&self) -> Self {
        *self
    }
}

impl<T> Copy for Tag<T> {}

impl<T> Tag<T> {
    const fn new(name: &'static str) -> Self {
        Self {
            name,
            kind: PhantomData,
        }
    }
}

impl<T: JsCast> Tag<T> {
    pub fn create(self) -> Result<T, JsValue> {
        document()?
            .create_element(self.name)?
            .dyn_into::<T>()
            .map_err(|_| JsValue::from_str(&format!("<{}> has another type", self.name)))
    }
}
"##;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn stylesheet_value_contracts_reject_drift_and_generate_typed_properties() {
        let mut names = Names::default();
        scan_css(
            "/* soiree-type: --accent color */\n.box { --accent: #fff; left: 0; color: red; background-image: none; animation-delay: 0s; }",
            &mut names,
        );
        let output = module(&Recipe::default(), &names).unwrap();
        for expected in [
            "VAR_ACCENT: super::Prop<salon_web::style::Color>",
            "LEFT: super::Prop<salon_web::style::Length>",
            "COLOR: super::Prop<salon_web::style::Color>",
            "BACKGROUND_IMAGE: super::Prop<salon_web::style::Image>",
            "ANIMATION_DELAY: super::Prop<salon_web::style::Time>",
        ] {
            assert!(output.contains(expected), "missing {expected}");
        }
        scan_css("/* soiree-type: --accent length */", &mut names);
        assert!(
            module(&Recipe::default(), &names).is_err(),
            "contradictory declarations passed"
        );
        for source in [
            "/* soiree-type: --missing color */",
            "/* soiree-type: color length */\n.box {color:red}",
            "/* soiree-type: --a invented */\n.box {--a:0}",
            "/* soiree-type: bad */",
        ] {
            let mut names = Names::default();
            scan_css(source, &mut names);
            assert!(
                module(&Recipe::default(), &names).is_err(),
                "accepted {source}"
            );
        }
    }

    #[test]
    fn html_gives_ids_classes_and_attributes() {
        let mut names = Names::default();
        scan_html(
            r#"<!-- <div id="ghost"> -->
            <h1 id="title" contenteditable="plaintext-only">T</h1>
            <div class="a b" data-zone="pool" hidden></div>
            <svg><filter id="clay"></filter></svg>
            <input id="name" title='a > b'>
            <style>.styled { margin: 0 }</style>
            <script>if (a<b) { x = "<div id='no'>"; }</script>"#,
            &mut names,
        )
        .unwrap();
        assert_eq!(
            names.ids.into_iter().collect::<Vec<_>>(),
            [
                ("clay".to_owned(), "svg".to_owned()),
                ("name".to_owned(), "input".to_owned()),
                ("title".to_owned(), "h1".to_owned()),
            ]
        );
        assert_eq!(
            names.classes.into_iter().collect::<Vec<_>>(),
            ["a", "b", "styled"]
        );
        assert_eq!(names.data.into_iter().collect::<Vec<_>>(), ["zone"]);
        assert_eq!(
            names.attrs.into_iter().collect::<Vec<_>>(),
            ["contenteditable", "hidden", "title"]
        );
    }

    #[test]
    fn a_duplicate_id_is_refused() {
        let mut names = Names::default();
        assert!(scan_html(r#"<p id="x"></p><p id="x"></p>"#, &mut names).is_err());
    }

    #[test]
    fn css_gives_selectors_and_properties() {
        let mut names = Names::default();
        scan_css(
            r##"/* .commented { } */
            :root { --hue: 10; }
            .swatch { background: var(--player-color, #fff); }
            .tier-row > .label[data-row], #title:hover { background-color: #fff; }
            @media (min-width: 40.5em) { .wide { margin-left: 2px } }
            @keyframes pop { from { opacity: 0 } 50% { opacity: .5 } }
            a[href^="#x"] { color: red }"##,
            &mut names,
        );
        assert_eq!(
            names.classes.into_iter().collect::<Vec<_>>(),
            ["label", "swatch", "tier-row", "wide"]
        );
        assert_eq!(names.css_ids.into_iter().collect::<Vec<_>>(), ["title"]);
        assert_eq!(names.data.into_iter().collect::<Vec<_>>(), ["row"]);
        assert_eq!(names.attrs.into_iter().collect::<Vec<_>>(), ["href"]);
        assert_eq!(
            names.props.into_iter().collect::<Vec<_>>(),
            [
                "--hue",
                "--player-color",
                "background",
                "background-color",
                "color",
                "margin-left",
                "opacity"
            ]
        );
    }

    #[test]
    fn names_become_constants() {
        assert_eq!(const_name("tier-row"), "TIER_ROW");
        assert_eq!(const_name("labelName"), "LABEL_NAME");
        assert_eq!(const_name("--hue"), "VAR_HUE");
        assert_eq!(const_name("2up"), "N2UP");
    }

    #[test]
    fn the_recipe_reads_back() {
        let recipe = parse_recipe(
            "// @generated by `soiree dom`: x\n// html: a.html\n// css: a.css b.css\n// id: labelName textarea\n// data: row\n\nuse x;",
        )
        .unwrap();
        assert_eq!(recipe.html, ["a.html"]);
        assert_eq!(recipe.css, ["a.css", "b.css"]);
        assert_eq!(
            recipe.ids,
            [("labelName".to_owned(), "textarea".to_owned())]
        );
        assert_eq!(recipe.data, ["row"]);
    }
}
